# ─── Job queue ────────────────────────────────────────────────────────────────

class _Queue:
    def __init__(self):
        self._lock   = threading.Lock()
        self.pending: list[dict] = []
        self.current: Optional[dict] = None
        self._thread: Optional[threading.Thread] = None

    def snapshot(self):
        with self._lock:
            return list(self.pending), (dict(self.current) if self.current else None)

    def enqueue(self, job: dict):
        with self._lock:
            self.pending.append(job)

    def _pop(self):
        with self._lock:
            if not self.pending:
                return None
            job = self.pending.pop(0)
            self.current = job
            return job

    def _done(self):
        with self._lock:
            self.current = None

    def ensure_worker(self):
        with self._lock:
            if self._thread and self._thread.is_alive():
                return
            t = threading.Thread(target=_worker_loop, daemon=True)
            self._thread = t
            t.start()

    def check_db_for_new_jobs(self):
        """Pick up any 'queued' jobs inserted into the DB by external processes (e.g. FastAPI upload)."""
        try:
            with self._lock:
                known = {j["id"] for j in self.pending}
                if self.current:
                    known.add(self.current["id"])
            for j in db.load_all_jobs():
                if j.get("status") == "queued" and j["id"] not in known:
                    self.enqueue(j)
            if self.pending:
                self.ensure_worker()
        except Exception:
            pass

    def recover_from_db(self):
        try:
            db.init_db()
            for j in reversed(db.load_all_jobs()):
                s = j.get("status")
                if s == "queued":
                    j["status_msg"] = "Waiting in queue…"
                    with self._lock:
                        self.pending.append(j)
                    db.save_job(j)
                elif s == "processing":
                    j["status"] = "error"
                    j["progress"] = 0.0
                    j["status_msg"] = "Interrupted — please re-upload"
                    j["error"] = "Server restarted during analysis."
                    db.save_job(j)
            if self.pending:
                self.ensure_worker()
        except Exception:
            pass


_mod = sys.modules[__name__]
if not hasattr(_mod, "_Q"):
    _q = _Queue()
    _q.recover_from_db()
    _mod._Q = _q
_Q: _Queue = _mod._Q


def _worker_loop():
    db.init_db()
    while True:
        try:
            job = _Q._pop()
            if job is None:
                time.sleep(0.5)
                continue

            job["status"] = "processing"
            job["progress"] = 0.0
            job["status_msg"] = "Starting…"
            db.save_job(job)

            import time as _t
            _last = 0.0

            def _cb(frac: float, msg: str):
                nonlocal _last
                with _Q._lock:
                    if _Q.current and _Q.current.get("id") == job["id"]:
                        _Q.current["progress"]   = frac
                        _Q.current["status_msg"] = msg
                job["progress"]   = frac
                job["status_msg"] = msg
                now = _t.time()
                if now - _last >= 1.0:
                    try: db.save_job(job)
                    except Exception: pass
                    _last = now

            try:
                from src.pipeline import run_pipeline
                job["result"]     = run_pipeline(job["path"], progress_cb=_cb, quarter_duration_ms=job.get("quarter_ms"))
                job["status"]     = "done"
                job["status_msg"] = "Complete ✓"
                job["progress"]   = 1.0
            except Exception as exc:
                job["status"]     = "error"
                job["error"]      = traceback.format_exc()
                job["status_msg"] = f"Error: {exc}"
                job["progress"]   = 0.0

            try: db.save_job(job)
            except Exception as e:
                job["result"] = None
                job["status"] = "error"
                job["error"]  = f"Save error: {e}"
                try: db.save_job(job)
                except Exception: pass

            with _Q._lock:
                if _Q.current and _Q.current.get("id") == job["id"]:
                    _Q.current.update(job)
            _Q._done()

        except Exception:
            try: _Q._done()
            except Exception: pass
            time.sleep(1.0)


# ─── Helpers ──────────────────────────────────────────────────────────────────

def _pct(v) -> str:
    if v is None: return "—"
    try: return f"{float(v)*100:.0f}%"
    except Exception: return "—"


def _get_session_user() -> Optional[dict]:
    uid = st.query_params.get("user_id")
    if uid:
        try:
            u = db.load_user(uid)
            if u:
                st.session_state["user"] = u
                return u
        except Exception:
            pass
    if "user" in st.session_state and st.session_state["user"]:
        return st.session_state["user"]
    return None


def _search_users(query: str) -> list[dict]:
    if not query or len(query.strip()) < 2:
        return []
    from src.database import get_conn
    q = f"%{query.strip().lower()}%"
    try:
        with get_conn() as conn:
            rows = conn.execute(
                """SELECT id, display_name, position, height_cm, age_group,
                          club_name, photo_b64
                   FROM users
                   WHERE lower(display_name) LIKE ?
                      OR lower(club_name)    LIKE ?
                      OR lower(position)     LIKE ?
                   LIMIT 20""",
                (q, q, q),
            ).fetchall()
        return [dict(r) for r in rows]
    except Exception:
        return []


