def _player_card_html(
    name: str,
    position: str = "",
    club: str = "",
    age_group: str = "",
    height_cm: Optional[int] = None,
    pts: int = 0,
    reb: int = 0,
    ast: int = 0,
    stl: int = 0,
    blk: int = 0,
    photo: str = "",
    jersey: str = "",
) -> str:
    avatar = photo if photo else DEFAULT_AVATAR
    # rating = pts when we have stats, jersey number otherwise
    rating = str(pts) if pts > 0 else (jersey.lstrip("#") if jersey else "—")
    pos_html = f'<div class="dc-card-pos">{_html.escape(position)}</div>' if position and position != "—" else ""
    badges = ""
    if age_group:
        badges += f'<span class="dc-badge-green">{_html.escape(age_group)}</span>'
    if club:
        badges += f'<span class="dc-badge-green">{_html.escape(club[:18])}</span>'
    height_html = f'<div class="dc-card-height">{height_cm} cm</div>' if height_cm else ""

    return (
        f'<div class="dc-player-card">'
        f'<div class="dc-card-shine"></div>'
        f'<div class="dc-card-header">'
        f'<div class="dc-card-rating">{rating}</div>'
        f'<div class="dc-card-pos-wrap">{pos_html}<div class="dc-card-flag">🇮🇱</div></div>'
        f'</div>'
        f'<div class="dc-card-av-wrap">'
        f'<div class="dc-card-av-ring"></div>'
        f'<img class="dc-card-av" src="{avatar}" alt="">'
        f'</div>'
        f'<div class="dc-card-body">'
        f'<div class="dc-card-name">{_html.escape(name)}</div>'
        f'<div class="dc-card-badges">{badges}</div>'
        f'{height_html}'
        f'<div class="dc-card-divider"></div>'
        f'<div class="dc-card-stats">'
        f'<div class="dc-card-stat"><span class="dc-card-sv dc-card-sv-pts">{pts}</span><span class="dc-card-sl">PTS</span></div>'
        f'<div class="dc-card-stat"><span class="dc-card-sv">{reb}</span><span class="dc-card-sl">REB</span></div>'
        f'<div class="dc-card-stat"><span class="dc-card-sv">{ast}</span><span class="dc-card-sl">AST</span></div>'
        f'<div class="dc-card-stat"><span class="dc-card-sv">{stl}</span><span class="dc-card-sl">STL</span></div>'
        f'<div class="dc-card-stat"><span class="dc-card-sv">{blk}</span><span class="dc-card-sl">BLK</span></div>'
        f'</div>'
        f'</div>'
        f'</div>'
    )


