def _render_search_results(query: str):
    users = _search_users(query)
    count = len(users)
    st.markdown(
        f'<div style="font-family:Poppins,sans-serif;font-size:16px;font-weight:700;'
        f'color:#fff;margin:20px 0 16px">'
        f'Search results for <span style="color:#7adb8f">"{_html.escape(query)}"</span>'
        f'{"&nbsp;·&nbsp;" + str(count) + " found" if count else ""}'
        f'</div>',
        unsafe_allow_html=True,
    )
    if not users:
        st.markdown(
            '<div style="color:rgba(255,255,255,0.38);font-size:14px;padding:40px 0;text-align:center">'
            'No players or clubs matched your search.</div>',
            unsafe_allow_html=True,
        )
        return

    cards_html = '<div class="dc-cards-grid">'
    for u in users:
        cards_html += _player_card_html(
            name      = u.get("display_name") or "—",
            position  = u.get("position") or "",
            club      = u.get("club_name") or "",
            age_group = u.get("age_group") or "",
            height_cm = u.get("height_cm"),
            photo     = u.get("photo_b64") or "",
        )
    cards_html += '</div>'
    st.markdown(cards_html, unsafe_allow_html=True)


