_POSITIONS = ["PG","SG","SF","PF","C"]


def _compute_age_group(birth_date: str, track: str) -> str:
    """Derive the Israeli basketball age group from birth date and competition track."""
    from datetime import date
    try:
        bd   = date.fromisoformat(str(birth_date)[:10])
        age  = (date.today() - bd).days // 365
        boys = (track or "boys") != "girls"
        if age <= 10: return "קטסל ב" if boys else "מיניות ב"
        if age == 11: return "קטסל א" if boys else "מיניות א"
        if age == 12: return "ילדים ב" if boys else "ילדות ב"
        if age == 13: return "ילדים א" if boys else "ילדות א"
        if age == 14: return "נערים ב" if boys else "נערות ב"
        if age == 15: return "נערים א" if boys else "נערות א"
        if age <= 17: return "נוער א"  if boys else "נוערות א"
        return "בוגרים" if boys else "בוגרות"
    except Exception:
        return ""


