def _render_edit_profile(user: dict):
    uid = user["id"]
    st.markdown(
        '<div style="font-family:Poppins,sans-serif;font-size:17px;font-weight:700;'
        'color:#fff;margin:28px 40px 14px">Edit Profile</div>',
        unsafe_allow_html=True,
    )
    pos_opts = ["PG", "SG", "SF", "PF", "C"]
    cur_pos  = user.get("position") or "PG"
    age_groups = [
        "קטסל ב", "קטסל א", "ילדים ב", "ילדים א",
        "נערים ב", "נערים א", "נוער ב", "נוער א", "בוגרים",
        "מיניות ב", "מיניות א", "ילדות ב", "ילדות א",
        "נערות ב", "נערות א", "נוערות ב", "נוערות א", "בוגרות",
    ]
    cur_ag = user.get("age_group") or ""

    with st.form("edit_profile_form", border=False):
        col_a, col_b = st.columns(2)
        with col_a:
            height   = st.number_input(
                "Height (cm)", min_value=100, max_value=230,
                value=int(user.get("height_cm") or 175), step=1,
            )
            position = st.selectbox(
                "Position", pos_opts,
                index=pos_opts.index(cur_pos) if cur_pos in pos_opts else 0,
            )
        with col_b:
            club = st.text_input("Club / Team", value=user.get("club_name") or "")
            age_group = st.selectbox(
                "Age Group", age_groups,
                index=age_groups.index(cur_ag) if cur_ag in age_groups else 0,
            )
        _, btn_col, _ = st.columns([0.14, 1, 0.14])
        with btn_col:
            saved = st.form_submit_button("Save Changes", use_container_width=True)
        if saved:
            db.patch_user(uid, height_cm=int(height), club_name=club.strip(),
                          age_group=age_group, position=position)
            st.success("Profile updated!")
            time.sleep(0.5)
            st.query_params["page"] = "profile"
            if "show" in st.query_params:
                del st.query_params["show"]
            st.rerun()


# ─── Floating Action Button ───────────────────────────────────────────────────

def _render_fab(user: dict):
    uid = user["id"]

    # FAB markup — NO onchange attributes.
    # Streamlit 1.56 converts st.markdown HTML to React elements via rehype-raw;
    # onchange="string" becomes onChange="string" in React, which throws error #231.
    # Handlers are wired separately from a sandboxed component iframe below.
    fab_html = (
        f'<div class="fab-wrap">'
        f'  <input type="checkbox" id="fab-toggle" class="fab-cb">'
        f'  <div class="fab-menu">'
        f'    <label for="fab-file-analyse" class="fab-item">Analyse Video</label>'
        f'    <label for="fab-file-other"   class="fab-item">Other Video</label>'
        f'  </div>'
        f'  <label for="fab-toggle" class="fab-btn"><span class="fab-icon">+</span></label>'
        f'  <input type="file" id="fab-file-analyse" accept=".mp4,.mkv,.avi,.webm,.mov" style="display:none">'
        f'  <input type="file" id="fab-file-other"   accept=".mp4,.mkv,.avi,.webm,.mov" style="display:none">'
        f'</div>'
    )
    st.markdown(fab_html, unsafe_allow_html=True)

    # Zero-height component iframe that wires up the file-input handlers.
    # Uses allow-same-origin to access window.parent.document (Streamlit layer),
    # and script-injection to navigate the Streamlit layer after upload.
    nav_analyse = f"http://localhost:8502/?user_id={uid}&page=profile"
    nav_other   = f"http://localhost:8502/?user_id={uid}&page=profile&section=other"

    _components.html(f"""<script>
(function() {{
  function navigate(url) {{
    try {{
      var s = window.parent.document.createElement('script');
      s.textContent = 'window.location.href=' + JSON.stringify(url) + ';';
      window.parent.document.head.appendChild(s);
      s.remove();
    }} catch(e) {{ console.error('navigate failed', e); }}
  }}

  /* Upload via hidden form + hidden iframe — bypasses CORS entirely */
  function uploadViaForm(file, fields, actionUrl, navUrl) {{
    var pd  = window.parent.document;
    var fid = '_dc_uf_' + Date.now();

    var frame = pd.createElement('iframe');
    frame.name = fid;
    frame.style.cssText = 'position:fixed;top:-9999px;left:-9999px;width:1px;height:1px';

    var form = pd.createElement('form');
    form.method  = 'POST';
    form.action  = actionUrl;
    form.enctype = 'multipart/form-data';
    form.target  = fid;
    form.style.cssText = 'display:none';

    /* Attach the File object to a file input via DataTransfer (parent realm) */
    var fi = pd.createElement('input');
    fi.type = 'file';
    fi.name = 'file';
    try {{
      var DTClass = window.parent.DataTransfer || DataTransfer;
      var dt = new DTClass();
      dt.items.add(file);
      fi.files = dt.files;
    }} catch(dtErr) {{
      /* DataTransfer unavailable — should not happen in modern Chrome/Firefox */
      console.error('DataTransfer failed:', dtErr);
      try {{ frame.remove(); }} catch(e2) {{}}
      navigate(navUrl);
      return;
    }}
    form.appendChild(fi);

    for (var k in fields) {{
      var hi = pd.createElement('input');
      hi.type = 'hidden'; hi.name = k; hi.value = fields[k];
      form.appendChild(hi);
    }}

    pd.body.appendChild(frame);
    pd.body.appendChild(form);

    var done = false;
    function cleanup() {{
      if (done) return; done = true;
      try {{ form.remove(); frame.remove(); }} catch(e) {{}}
      navigate(navUrl);
    }}
    frame.addEventListener('load', function() {{ setTimeout(cleanup, 300); }});
    setTimeout(cleanup, 60000); /* 60 s hard timeout */

    form.submit();
  }}

  function handleAnalyse() {{
    var f = this.files[0]; if (!f) return;
    var tog = window.parent.document.getElementById('fab-toggle');
    if (tog) tog.checked = false;
    uploadViaForm(f, {{user_id: '{uid}'}},
                  'http://localhost:8510/api/upload/analyse', '{nav_analyse}');
  }}

  function handleOther() {{
    var f = this.files[0]; if (!f) return;
    var fileName = f.name;
    var tog = window.parent.document.getElementById('fab-toggle');
    if (tog) tog.checked = false;

    var pd = window.parent.document;
    var overlay = pd.createElement('div');
    overlay.id = '_dc_modal_overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99999;display:flex;align-items:center;justify-content:center';
    overlay.innerHTML = (
      '<div style="background:#0a3d22;border-radius:10px;padding:28px 28px 20px;width:340px;box-shadow:0 8px 32px rgba(0,0,0,.5);font-family:Poppins,sans-serif">' +
      '<div style="color:#7adb8f;font-weight:700;font-size:15px;margin-bottom:4px">Add a description</div>' +
      '<div style="color:#b0c8bc;font-size:12px;margin-bottom:14px">' + fileName + '</div>' +
      '<input id="_dc_modal_input" type="text" placeholder="e.g. Ball handling drills..." autocomplete="off" ' +
        'style="width:100%;padding:10px 12px;border-radius:6px;border:1.5px solid #7adb8f44;background:#054530;color:#fff;font-size:14px;outline:none;font-family:inherit;box-sizing:border-box">' +
      '<div style="display:flex;gap:10px;margin-top:16px;justify-content:flex-end">' +
        '<button id="_dc_modal_cancel" style="padding:8px 18px;border-radius:6px;border:1.5px solid #7adb8f66;background:transparent;color:#7adb8f;font-size:13px;cursor:pointer;font-family:inherit">Cancel</button>' +
        '<button id="_dc_modal_upload" style="padding:8px 18px;border-radius:6px;border:none;background:#7adb8f;color:#054530;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit">Upload</button>' +
      '</div></div>'
    );
    pd.body.appendChild(overlay);
    pd.getElementById('_dc_modal_input').focus();

    function closeModal() {{ var o = pd.getElementById('_dc_modal_overlay'); if (o) o.remove(); }}

    pd.getElementById('_dc_modal_cancel').onclick = function() {{ closeModal(); }};
    pd.getElementById('_dc_modal_upload').onclick = function() {{
      var title = (pd.getElementById('_dc_modal_input').value || '').trim();
      closeModal();
      var fields = {{user_id: '{uid}'}};
      if (title) fields.title = title;
      uploadViaForm(f, fields, 'http://localhost:8510/api/upload/other', '{nav_other}');
    }};
    pd.getElementById('_dc_modal_input').onkeydown = function(e) {{
      if (e.key === 'Enter') pd.getElementById('_dc_modal_upload').click();
      if (e.key === 'Escape') closeModal();
    }};
  }}

  setInterval(function() {{
    var a = window.parent.document.getElementById('fab-file-analyse');
    var o = window.parent.document.getElementById('fab-file-other');
    if (a && !a._dcBound) {{ a._dcBound = true; a.addEventListener('change', handleAnalyse); }}
    if (o && !o._dcBound) {{ o._dcBound = true; o.addEventListener('change', handleOther); }}
  }}, 400);
}})();
</script>""", height=0, scrolling=False)


# ─── Analyse Videos page ──────────────────────────────────────────────────────

def _render_analyse_videos(user: dict):
    """View all the user's analysed games with full stats, video, and invite."""
    uid = user["id"]
    st.markdown('<div class="dc-section-title" style="margin-top:8px">Analysed Games</div>', unsafe_allow_html=True)

    user_jobs = db.load_jobs_by_user(uid)
    done_jobs = [j for j in user_jobs if j.get("status") == "done"]

    # teammates for invite
    all_memberships = db.load_team_memberships()
    user_team_ids   = {m["team_id"] for m in all_memberships if m["user_id"] == uid}
    teammates       = [m for m in all_memberships if m["team_id"] in user_team_ids and m["user_id"] != uid]

    if not done_jobs:
        st.markdown(
            '<div style="color:rgba(255,255,255,0.35);font-size:14px;padding:60px 0;text-align:center">'
            'No analysed games yet.<br>Use the <strong style="color:#7adb8f">+</strong> button to upload a game for analysis.</div>',
            unsafe_allow_html=True,
        )
        return

    selected_key = "av_selected_job"
    selected_id  = st.session_state.get(selected_key)

    # Left sidebar: game list
    col_list, col_detail = st.columns([1, 3])

    with col_list:
        st.markdown('<div class="dc-section-title">Games</div>', unsafe_allow_html=True)
        for job in done_jobs:
            is_active = selected_id == job["id"]
            cls = "dc-game-card active" if is_active else "dc-game-card"
            result    = job.get("result") or {}
            n_players = len((result.get("box_score") or {}).get("players") or [])
            st.markdown(
                f'<div class="{cls}">'
                f'<div class="dc-game-name">{_html.escape(job["name"])}</div>'
                f'<div class="dc-game-meta"><span class="dc-st-done">✓ Done</span> · {n_players} players</div>'
                f'</div>',
                unsafe_allow_html=True,
            )
            if st.button("View", key=f"av_sel_{job['id']}", use_container_width=True):
                st.session_state[selected_key] = job["id"]
                st.rerun()

    with col_detail:
        job = next((j for j in done_jobs if j["id"] == selected_id), done_jobs[0] if done_jobs else None)
        if not job:
            return
        st.session_state[selected_key] = job["id"]

        # Video player
        video_path = job.get("path", "")
        if video_path and Path(video_path).exists():
            st.video(video_path)
        else:
            st.markdown(
                '<div style="background:rgba(255,255,255,0.04);border-radius:10px;'
                'padding:28px;text-align:center;color:rgba(255,255,255,0.3);margin-bottom:16px">'
                '🎬 Video file not found on disk</div>',
                unsafe_allow_html=True,
            )

        # Full results (box score + PbP + learning)
        _render_results(job)

        # Invite teammates
        st.markdown('<div class="dc-section-title" style="margin-top:20px">Invite Teammates</div>', unsafe_allow_html=True)
        if teammates:
            existing_invites = {i["user_id"] for i in db.load_game_invites() if i.get("game_id") == job["id"]}
            for tm in teammates:
                row_l, row_r = st.columns([4, 1])
                with row_l:
                    st.markdown(
                        f'<span class="dc-invite-name">👤 {_html.escape(tm["display_name"])}'
                        f' <span style="color:rgba(255,255,255,0.3);font-size:11px">· {_html.escape(tm["team_name"])}</span></span>',
                        unsafe_allow_html=True,
                    )
                with row_r:
                    if tm["user_id"] in existing_invites:
                        st.markdown('<span class="dc-invite-sent">✓ Invited</span>', unsafe_allow_html=True)
                    elif st.button("Invite", key=f"inv_{job['id']}_{tm['user_id']}"):
                        db.save_game_invite(game_id=job["id"], user_id=tm["user_id"], invited_email=tm.get("email"))
                        st.rerun()
        else:
            st.markdown(
                '<div style="color:rgba(255,255,255,0.3);font-size:13px;font-family:Poppins,sans-serif">'
                'Join a team to invite teammates.</div>',
                unsafe_allow_html=True,
            )


