def _render_other_videos(user: dict):
    """View casual (non-analysis) videos the user has uploaded."""
    uid = user["id"]
    st.markdown(
        '<div class="dc-section-title" style="margin-top:8px;margin-left:12px">Other Videos</div>',
        unsafe_allow_html=True,
    )

    videos = db.load_other_videos_by_user(uid)

    if not videos:
        st.markdown(
            '<div style="color:rgba(255,255,255,0.35);font-size:14px;padding:60px 0;text-align:center">'
            'No videos yet.<br>Use the <strong style="color:#7adb8f">+</strong> button to upload a video.</div>',
            unsafe_allow_html=True,
        )
        return

    # Left margin on titles and video players in this section
    st.markdown(
        '<style>[data-testid="stVideo"]{padding-left:12px!important}'
        '.dc-ov-label{margin-left:12px}</style>',
        unsafe_allow_html=True,
    )

    # 3 per row; date label below each video player, no title above
    rows = [videos[i:i+3] for i in range(0, len(videos), 3)]
    for row in rows:
        cols = st.columns([1, 1, 1], gap="medium")
        for col, v in zip(cols, row):
            with col:
                if Path(v["file_path"]).exists():
                    st.video(v["file_path"])
                else:
                    st.markdown(
                        '<div style="height:100px;background:rgba(255,255,255,0.04);'
                        'border-radius:8px;display:flex;align-items:center;justify-content:center;'
                        'color:rgba(255,255,255,0.25);font-size:12px;font-family:Poppins,sans-serif">'
                        'File not found</div>',
                        unsafe_allow_html=True,
                    )
                desc = v.get("title", "").strip()
                date = v.get("created_at", "")[:10]
                st.markdown(
                    f'<div class="dc-ov-label" style="margin-bottom:12px">'
                    + (f'<div class="dc-vid-card-title" style="font-size:13px">{_html.escape(desc)}</div>' if desc else "")
                    + f'<div class="dc-vid-card-meta">{date}</div>'
                    f'</div>',
                    unsafe_allow_html=True,
                )


# ─── Upload pages (from FAB) ──────────────────────────────────────────────────

def _trigger_file_picker(input_index: int = 0) -> None:
    """Inject JS that clicks the nth Streamlit file input in the parent page."""
    _components.html(
        f"""<script>
        (function() {{
            var n = {input_index};
            var attempts = 0;
            var iv = setInterval(function() {{
                var inputs = window.parent.document.querySelectorAll(
                    '[data-testid="stFileUploaderDropzoneInput"]'
                );
                if (inputs[n]) {{ inputs[n].click(); clearInterval(iv); }}
                if (++attempts > 30) clearInterval(iv);
            }}, 80);
        }})();
        </script>""",
        height=0,
        scrolling=False,
    )


def _render_upload_analyse(user: dict):
    """Dedicated upload page → queues video for pipeline analysis, saved per user."""
    uid = user["id"]
    st.markdown('<div class="dc-upload-title">🎬 Upload Game for Analysis</div>', unsafe_allow_html=True)
    st.markdown(
        '<div style="color:rgba(255,255,255,0.45);font-size:13px;font-family:Poppins,sans-serif;margin-bottom:20px">'
        'Upload a game video. Our AI will detect players, generate box scores, play-by-play, and learning moments.</div>',
        unsafe_allow_html=True,
    )

    uploaded = st.file_uploader("Game video", type=["mp4", "mkv", "avi", "webm", "mov"], label_visibility="collapsed")
    if not uploaded:
        _trigger_file_picker(0)
    if uploaded:
        st.caption(f"📄 {uploaded.name}  ·  {uploaded.size/1_000_000:.1f} MB")
        col_a, col_b = st.columns(2)
        with col_a:
            scope = st.selectbox("Game scope", [
                "full_game", "first_half", "second_half",
                "quarter_1", "quarter_2", "quarter_3", "quarter_4", "overtime",
            ])
        with col_b:
            q_len = st.selectbox("Quarter length (min)", [8, 10, 12, 20])

        if st.button("🚀 Start Analysis", use_container_width=True):
            submit_key = f"_submitted_analyse_{uploaded.file_id}"
            if not st.session_state.get(submit_key):
                st.session_state[submit_key] = True
                ext  = Path(uploaded.name).suffix
                jid  = uuid.uuid4().hex
                path = VIDEO_DIR / f"{jid}{ext}"
                path.write_bytes(uploaded.read())
                job = {
                    "id":         jid,
                    "name":       uploaded.name,
                    "path":       str(path),
                    "status":     "queued",
                    "progress":   0.0,
                    "status_msg": "Queued",
                    "result":     None,
                    "error":      None,
                    "quarter_ms": q_len * 60 * 1000,
                    "user_id":    uid,
                }
                db.save_job(job)
                _Q.enqueue(job)
                _Q.ensure_worker()
                st.success(f"✅ **{uploaded.name}** queued for analysis!")
                time.sleep(0.8)
                # Navigate to analyse videos page to watch progress
                st.query_params["page"] = "analyse_videos"
                st.rerun()


def _render_upload_other(user: dict):
    """Dedicated upload page → saves casual video to DB (no analysis)."""
    uid = user["id"]
    st.markdown('<div class="dc-upload-title">📹 Upload Other Video</div>', unsafe_allow_html=True)
