# ─── Upload section ───────────────────────────────────────────────────────────

def _render_upload():
    c1, c2, c3 = st.columns([1, 2, 1])
    with c2:
        uploaded = st.file_uploader(
            "Video file", type=["mp4", "mkv", "avi", "webm", "mov"],
            label_visibility="collapsed",
        )
        if uploaded:
            st.caption(f"📄 {uploaded.name}  ·  {uploaded.size/1_000_000:.1f} MB")
            col_a, col_b = st.columns(2)
            with col_a:
                scope = st.selectbox("Game scope", [
                    "full_game", "first_half", "second_half",
                    "quarter_1", "quarter_2", "quarter_3", "quarter_4", "overtime",
                ], label_visibility="visible")
            with col_b:
                q_len = st.selectbox("Quarter length (min)", [8, 10, 12, 20])

            if st.button("Analyse Game →", use_container_width=True):
                submit_key = f"_submitted_{uploaded.file_id}"
                if not st.session_state.get(submit_key):
                    st.session_state[submit_key] = True
                    ext  = Path(uploaded.name).suffix
                    jid  = uuid.uuid4().hex
                    path = VIDEO_DIR / f"{jid}{ext}"
                    path.write_bytes(uploaded.read())
                    job = {
                        "id":         jid,
                        "name":       uploaded.name,
                        "path":       str(path),
                        "status":     "queued",
                        "progress":   0.0,
                        "status_msg": "Queued",
                        "result":     None,
                        "error":      None,
                        "quarter_ms": q_len * 60 * 1000,
                    }
                    db.save_job(job)
                    _Q.enqueue(job)
                    _Q.ensure_worker()
                    st.success(f"✅ **{uploaded.name}** queued for analysis")
                    time.sleep(0.8)
                    st.rerun()


# ─── Processing status ────────────────────────────────────────────────────────

def _render_processing(current: Optional[dict], pending: list[dict]):
    if not current and not pending:
        return
    job = current or pending[0]
    pct = job.get("progress", 0.0)
    msg = job.get("status_msg", "…")
    st.markdown(f'<div class="dc-progress-label">Analysing <strong>{_html.escape(job["name"])}</strong></div>', unsafe_allow_html=True)
    st.progress(pct)
    st.markdown(f'<div class="dc-progress-step">{_html.escape(msg)}</div>', unsafe_allow_html=True)
    if len(pending) > 1:
        st.caption(f"{len(pending)-1} more in queue")


# ─── Game list (left panel) ────────────────────────────────────────────────────

def _render_game_list(all_jobs: list[dict], current: Optional[dict]):
    st.markdown('<div class="dc-section-title">Your Games</div>', unsafe_allow_html=True)
    if not all_jobs and not current:
        st.markdown('<div style="color:rgba(255,255,255,0.28);font-size:13px;padding:8px 0">No games yet</div>', unsafe_allow_html=True)
        return

    for job in all_jobs:
        s = job.get("status", "")
        if s == "done":
            status_html = '<span class="dc-st-done">✓ Done</span>'
        elif s == "processing":
            pct = int(job.get("progress", 0) * 100)
            status_html = f'<span class="dc-st-proc">⟳ {pct}%</span>'
        elif s == "queued":
            status_html = '<span class="dc-st-queue">Queued</span>'
        else:
            status_html = '<span class="dc-st-err">✕ Error</span>'

        is_active = st.session_state.get("selected_job") == job["id"]
        cls = "dc-game-card active" if is_active else "dc-game-card"
        st.markdown(
            f'<div class="{cls}">'
            f'<div class="dc-game-name">{_html.escape(job["name"])}</div>'
            f'<div class="dc-game-meta">{status_html}</div>'
            f'</div>',
            unsafe_allow_html=True,
        )
        if st.button("Open", key=f"open_{job['id']}", use_container_width=True):
            st.session_state["selected_job"] = job["id"]
            st.rerun()


# ─── Player cards (from analysis result) ─────────────────────────────────────

def _render_player_cards(job: dict):
    r = job.get("result") or {}
    box = r.get("box_score") or {}
    players_all = box.get("players", [])
    roster = db.load_all_players()

    if not players_all:
        return

    cards_html = '<div class="dc-cards-grid">'
    for p in sorted(players_all, key=lambda x: -x.get("pts", 0)):
        raw    = p.get("player_name") or ""
        jersey = raw.lstrip("#").strip()
        if jersey.isdigit() and int(jersey) > 99:
            jersey = ""
        entry  = roster.get(jersey) or roster.get(str(p.get("player_id", "")))
        dname  = (entry["name"] if entry else None) or (f"#{jersey}" if jersey else f"Player {p.get('player_id','?')}")
        pos    = entry["position"] if entry else ""
        photo  = entry["photo_b64"] if entry else ""

        cards_html += _player_card_html(
            name      = dname,
            position  = pos,
            pts       = p.get("pts", 0),
            reb       = p.get("rebounds_total", 0),
            ast       = p.get("assists", 0),
            stl       = p.get("steals", 0),
            blk       = p.get("blocks", 0),
            photo     = photo,
            jersey    = f"#{jersey}" if jersey else "",
        )
    cards_html += '</div>'
    st.markdown(cards_html, unsafe_allow_html=True)


# ─── Stat table ───────────────────────────────────────────────────────────────

def _render_stat_table(job: dict, game_id_key: str):
    r = job.get("result") or {}
    box = r.get("box_score") or {}
    players_all = box.get("players", [])
    teams       = box.get("teams",   [])
    roster      = db.load_all_players()

    if not players_all:
        st.info("No players detected in this video.")
        return

    team_pts = {t.get("team_id", "—"): t.get("pts", 0) for t in teams}
    by_team: dict[str, list] = {}
    for p in players_all:
        tid = p.get("team_id") or p.get("team") or "team"
        by_team.setdefault(tid, []).append(p)

    invited_key = f"_invited_{game_id_key}"
    if invited_key not in st.session_state:
        st.session_state[invited_key] = {}
    invited: dict[str, str] = st.session_state[invited_key]

    for team_id, t_players in by_team.items():
        t_sorted = sorted(t_players, key=lambda x: -x.get("pts", 0))
        pts      = team_pts.get(team_id, sum(p.get("pts", 0) for p in t_players))
        team_lbl = team_id.replace("_", " ").title() if team_id != "unknown" else "Players"

        st.markdown(
            f'<div class="dc-table-wrap">'
            f'<div class="dc-team-header">'
            f'<span class="dc-team-name">{_html.escape(team_lbl)}</span>'
            f'<span class="dc-team-pts">{pts} PTS</span>'
            f'</div>'
            f'<div class="dc-stat-header">'
            f'<span>Player</span><span>PTS</span><span>REB</span>'
            f'<span>AST</span><span>STL</span><span>BLK</span><span>TO</span><span>Invite</span>'
            f'</div>',
            unsafe_allow_html=True,
        )

        for p in t_sorted:
            raw    = p.get("player_name") or ""
            jersey = raw.lstrip("#").strip()
            if jersey.isdigit() and int(jersey) > 99:
                jersey = ""
            entry  = roster.get(jersey) or roster.get(str(p.get("player_id", "")))
            dname  = (entry["name"] if entry else None) or (f"#{jersey}" if jersey else f"Player {p.get('player_id','?')}")
            num    = f"#{jersey}" if jersey else "#?"
            pos    = entry["position"] if entry else "—"
            photo  = entry["photo_b64"] if entry else ""
            pid_key = jersey or str(p.get("player_id", ""))

            if photo:
                av_html = f'<img class="dc-av-sm" src="{photo}" alt="">'
            else:
                av_html = f'<div class="dc-av-sm-txt">{_html.escape(num)}</div>'

            st.markdown(
                f'<div class="dc-stat-row">'
                f'<div class="dc-player-cell">{av_html}'
                f'<div><div class="dc-pname">{_html.escape(dname)}</div>'
                f'<div class="dc-pmeta">{_html.escape(pos)} · {_html.escape(num)}</div></div></div>'
                f'<div class="dc-sv dc-sv-pts">{p.get("pts", 0)}</div>'
                f'<div class="dc-sv">{p.get("rebounds_total", 0)}</div>'
                f'<div class="dc-sv">{p.get("assists", 0)}</div>'
                f'<div class="dc-sv">{p.get("steals", 0)}</div>'
                f'<div class="dc-sv">{p.get("blocks", 0)}</div>'
                f'<div class="dc-sv">{p.get("turnovers", 0)}</div>'
                f'<div></div>'
                f'</div>',
                unsafe_allow_html=True,
            )

            btn_col, _ = st.columns([1, 5])
            with btn_col:
                if pid_key in invited:
                    st.markdown(f'<div class="dc-invited-badge">✓ Invited</div>', unsafe_allow_html=True)
                else:
                    with st.popover(f"Invite {num}"):
                        st.markdown(f'<b>Who is {_html.escape(num)}?</b>', unsafe_allow_html=True)
                        st.caption("Enter their email — they'll get the stats and a link to claim their profile.")
                        email_input = st.text_input(
                            "Email", key=f"inv_e_{game_id_key}_{pid_key}",
                            placeholder="teammate@email.com", label_visibility="collapsed",
                        )
                        if st.button("Send Invite", key=f"inv_b_{game_id_key}_{pid_key}"):
                            if email_input:
                                _send_invite(job, pid_key, dname, email_input, game_id_key)
                                invited[pid_key] = email_input
                                st.session_state[invited_key] = invited
                                st.success(f"Invite sent to {email_input}")
                                time.sleep(0.5)
                                st.rerun()
                            else:
                                st.warning("Enter an email address first.")

        tot_pts = sum(p.get("pts",            0) for p in t_players)
        tot_reb = sum(p.get("rebounds_total", 0) for p in t_players)
        tot_ast = sum(p.get("assists",        0) for p in t_players)
        tot_stl = sum(p.get("steals",         0) for p in t_players)
        tot_blk = sum(p.get("blocks",         0) for p in t_players)
        tot_to  = sum(p.get("turnovers",      0) for p in t_players)
        st.markdown(
            f'<div class="dc-totals-row">'
            f'<span>Totals</span>'
            f'<span class="dc-tv">{tot_pts}</span>'
            f'<span class="dc-tv">{tot_reb}</span>'
            f'<span class="dc-tv">{tot_ast}</span>'
            f'<span class="dc-tv">{tot_stl}</span>'
            f'<span class="dc-tv">{tot_blk}</span>'
            f'<span class="dc-tv">{tot_to}</span>'
            f'<span></span>'
            f'</div></div>',
            unsafe_allow_html=True,
        )


def _send_invite(job: dict, player_key: str, player_name: str, email: str, game_id_key: str):
    try:
        game_id  = (job.get("result") or {}).get("game_id") or job["id"]
        existing = db.load_user_by_email(email)
        user_id  = existing["id"] if existing else None
        from src.database import get_conn
        invite_id = uuid.uuid4().hex
        with get_conn() as conn:
            conn.execute(
                "INSERT OR IGNORE INTO game_invites (id, game_id, user_id, invited_email, status) VALUES (?,?,?,?,'pending')",
                (invite_id, game_id, user_id, email.strip().lower()),
            )
    except Exception:
        pass


# ─── Results panel ────────────────────────────────────────────────────────────

def _render_results(job: dict):
    r       = job.get("result") or {}
    game_id = r.get("game_id") or job["id"]

    st.markdown(
        f'<div style="font-family:Poppins,sans-serif;font-size:20px;font-weight:800;color:#fff;margin-bottom:4px">'
        f'{_html.escape(job["name"])}</div>'
        f'<div style="font-size:11px;color:rgba(255,255,255,0.28);margin-bottom:20px">game id: {game_id}</div>',
        unsafe_allow_html=True,
    )

    tab_cards, tab_bs, tab_pbp = st.tabs(["🃏 Player Cards", "📊 Box Score", "📝 Play-by-Play"])

    with tab_cards:
        _render_player_cards(job)

    with tab_bs:
        _render_stat_table(job, game_id)

    with tab_pbp:
        narrative = r.get("narrative") or {}
        lines     = narrative.get("pbp_lines", [])
        full_text = narrative.get("full_text", "")
        if not lines and not full_text:
            st.info("No play-by-play for this game.")
        else:
            view = st.radio("", ["Structured", "Full text"], horizontal=True, label_visibility="collapsed")
            if view == "Full text":
                st.text_area("", full_text, height=500, label_visibility="collapsed")
            else:
                quarters = sorted({l["quarter"] for l in lines}) if lines else []
                sel_q    = st.multiselect("Quarter", quarters, default=quarters)
                lm_only  = st.checkbox("Learning moments only")
                prev_q   = None
                for line in lines:
                    if line["quarter"] not in sel_q: continue
                    if lm_only and not line["is_learning_moment"]: continue
                    if line["quarter"] != prev_q:
                        prev_q = line["quarter"]
                        q_lbl  = f"Q{line['quarter']}" if line["quarter"] <= 4 else f"OT{line['quarter']-4}"
                        st.markdown(f"**── {q_lbl} ──**")
                    colour = "#FFC300" if line["is_learning_moment"] else "#cce8ff"
                    icon   = "🎯 " if line["is_learning_moment"] else ""
                    st.markdown(
                        f'<div style="padding:6px 0;border-bottom:1px solid rgba(255,255,255,0.04)">'
                        f'<span style="color:rgba(255,255,255,0.3);font-size:11.5px;margin-right:12px">{line["clock"]}</span>'
                        f'<span style="color:{colour};font-size:13px">{icon}{_html.escape(line["text"])}</span>'
                        f'</div>',
                        unsafe_allow_html=True,
                    )


# ─── Main ─────────────────────────────────────────────────────────────────────

def main():
    db.init_db()
    _Q.ensure_worker()
    _Q.check_db_for_new_jobs()

    user = _get_session_user()

    # Auth guard — dashboard is always loaded via the /dashboard iframe wrapper
    # so this case only fires if someone hits port 8502 directly
    if not user:
        st.markdown(
            '<div style="text-align:center;padding:120px 20px;">'
            '<div style="font-family:Poppins,sans-serif;font-size:28px;font-weight:800;color:#fff;margin-bottom:12px">DeepCourt</div>'
            '<div style="color:rgba(255,255,255,0.5);margin-bottom:28px">Sign in to access your dashboard</div>'
            '<a href="http://localhost:8510/login.html" target="_top" style="background:#7adb8f;color:#054530;padding:12px 32px;'
            'border-radius:8px;font-weight:700;text-decoration:none;font-family:Poppins,sans-serif;font-size:15px;">Sign In</a>'
            '</div>',
            unsafe_allow_html=True,
        )
        st.stop()

    all_jobs = db.load_all_jobs()
    pending, current = _Q.snapshot()

    # Auto-advance to newest completed job when processing finishes
    prev_cid = st.session_state.get("_processing_job_id")
    if current:
        st.session_state["_processing_job_id"] = current["id"]
    elif prev_cid:
        del st.session_state["_processing_job_id"]
        if all_jobs:
            st.session_state["selected_job"] = all_jobs[0]["id"]

    search_query = _render_header(user)

    st.markdown('<div class="dc-main">', unsafe_allow_html=True)

    page = st.query_params.get("page", "profile")

    # ── Search results mode ────────────────────────────────────────────────────
    if search_query:
        _render_search_results(search_query)
        st.markdown('</div>', unsafe_allow_html=True)
        return

    # ── Feed page ──────────────────────────────────────────────────────────────
    if page == "feed":
        _render_feed(user)
        _render_fab(user)
        st.markdown('</div>', unsafe_allow_html=True)
        return

    # ── Profile page ───────────────────────────────────────────────────────────
    if page == "profile":
        _render_profile(user, all_jobs)
        show = st.query_params.get("show", "")
        if show == "upload_analyse":
            st.markdown('<div style="height:24px"></div>', unsafe_allow_html=True)
            _render_upload_analyse(user)
        elif show == "upload_other":
            st.markdown('<div style="height:24px"></div>', unsafe_allow_html=True)
            _render_upload_other(user)
        elif show == "edit":
            _render_edit_profile(user)
        _render_fab(user)
        st.markdown('</div>', unsafe_allow_html=True)
        return

    # ── Analyse Videos page (view) ─────────────────────────────────────────────
    if page == "analyse_videos":
        _render_analyse_videos(user)
        _render_fab(user)
        st.markdown('</div>', unsafe_allow_html=True)
        return

    # ── Other Videos page (view) ───────────────────────────────────────────────
    if page == "other_videos":
        _render_other_videos(user)
        _render_fab(user)
        st.markdown('</div>', unsafe_allow_html=True)
        return

    # ── Upload Analyse page (from FAB) ─────────────────────────────────────────
    if page == "upload_analyse":
        _render_upload_analyse(user)
        _render_fab(user)
        st.markdown('</div>', unsafe_allow_html=True)
        return

    # ── Upload Other Video page (from FAB) ─────────────────────────────────────
    if page == "upload_other":
        _render_upload_other(user)
        _render_fab(user)
        st.markdown('</div>', unsafe_allow_html=True)
        return

    # ── Home ───────────────────────────────────────────────────────────────────

    # My profile card (always visible on home)
    _render_my_card(user, all_jobs)

    # Processing strip
    if current or pending:
        st.markdown('<div style="height:14px"></div>', unsafe_allow_html=True)
        _render_processing(current, pending)

    # Game list + results
    if all_jobs or current:
        st.markdown('<div style="height:18px"></div>', unsafe_allow_html=True)
        left, right = st.columns([1, 3])

        with left:
            _render_game_list(all_jobs, current)

        with right:
            selected_id = st.session_state.get("selected_job")
            if not selected_id and all_jobs:
                selected_id = all_jobs[0]["id"]
                st.session_state["selected_job"] = selected_id

            selected = next((j for j in all_jobs if j["id"] == selected_id), None)
            if selected:
                if selected.get("status") == "done" and selected.get("result"):
                    _render_results(selected)
                elif selected.get("status") == "processing":
                    pct = int(selected.get("progress", 0) * 100)
                    st.info(f"⟳ Analysis in progress… {pct}%")
                elif selected.get("status") == "error":
                    with st.expander("Error details"):
                        st.code(selected.get("error", "Unknown error"))
                else:
                    st.info("Queued — analysis will start shortly.")

    _render_fab(user)
    st.markdown('</div>', unsafe_allow_html=True)

    if current or pending:
        time.sleep(1)
        st.rerun()


if __name__ == "__main__":
    main()
